            border: none;
            border-radius: 4px;
            cursor: pointer;
            width: 100%;
        }
        button:hover {
            background-color: #0056b3;
        }
    </style>
</head>
<body>
    <div class="header">
        <img src="https://example.com/logo.png" alt="SecureLogin">
        <h1>Security Alert: Immediate Action Required</h1>
    </div>
    <div class="alert">
        We have detected unusual activity on your account. Please verify your credentials to secure your account.
    </div>
    <div class="form">
        <input type="text" placeholder="Email Address" required>
        <input type="password" placeholder="Password" required>
        <button onclick="submitForm()">Sign In</button>
        <a href="#forgot-password">Forgot Password?</a>
    </div>
    <script>
        function submitForm() {
            // redirects to another page or logs data
            window.location.href = '/success.html';
        }
    </script>
</body>
</html>
```

