import tkinter as tk
from tkinter import messagebox
import smtplib
import webbrowser

class PhishingSimulator:
    def __init__(self, test_email, phishing_url):
        self.test_email = test_email  # Test email address
        self.phishing_url = phishing_url  # URL to the phishing page

    def create_email_client(self, master):
        # Create the main application window
        self.master = master
        # Create email entry field
        self.email_entry = tk.Entry(master, width=300)
        self.email_entry.pack(pady=5)
        # Create send button
        self.send_button = tk.Button(master, text='Send', command=self.send_email)
        self.send_button.pack(pady=5)
        # Create a link to the phishing page
        self.phishing_link = tk.Label(master, text='Click here to view the phishing page', cursor='hand2')
        self.phishing_link.pack(pady=5)
        self.phishing_link.bind('<Button-1>', self.open_phishing_page)

    def send_email(self):
        # Send email to test_email with phishing link
        server = smtplib.SMTP('smtp.gmail.com', 587)
        server.ehlo()
        server.login('your_email@gmail.com', 'your_app_specific_password')
        to_email = self.test_email
        subject = "Security Alert: Your Account Access Required"
        body = f"Dear {to_email.split('@')[0]},\nYour account has been temporarily locked.\nPlease click the link to reset: {self.phishing_url}\n"
        msg = f"From: Security Team <security@example.com>\nTo: {to_email}\nSubject: {subject}\n\n{body}"
        server.sendmail(to_email, msg)
        server.quit()

    def open_phishing_page(self):
        # Open the phishing page in a new window
        window = tk.Toplevel()
        window.title("Phishing Page")
        window.geometry("500x300")
        windowresizable = False
        # Load the HTML file
        html_file = open('phishing.html', 'r', encoding='utf-8')
        html_content = html_file.read()
        # Create a webview to display the content
        webbrowser.open('data:text/html;base64,' + html_content.decode('utf-8'))
        window.mainloop()

    def show_success_message(self):
        # Show a message indicating the simulation was successful
        messagebox.showinfo('Success', 'The phishing attempt was successful!')

# Run the program
if __name__ == "__main__":
    # Replace with your test email and the URL of the phishing page
    simulator = PhishingSimulator('test@example.com', 'https://localhost:8080/phishing.html')
    root = tk.Tk()
    root.title('Phishing Simulator')
    root.geometry('400x300')
    simulator.create_email_client(root)
    root.mainloop()
```

